/* yc-live.js - the programme bench for learn-yoga-course-design-with-phoebe
 *
 * CONSTRUCTED, end to end. Juniper Studio, its 12-student beginner cohort, the 42-pose library,
 * every load and complexity level (a 1 to 5 teaching scale) and every plan are invented for
 * teaching. Flags are referral and caution tags, never a diagnosis. Data: assets/yc-data.js,
 * generated by materials/build_yc_data.py. Python reference: materials/yc_reference.py, which
 * must agree with this file exactly (integer arithmetic throughout).
 *
 * The rules, in plain words:
 *   - A plan is 8 weekly classes, each an ordered list of poses.
 *   - Prerequisite gap: a pose whose prerequisite was not met in an earlier week, or earlier in
 *     the same class.
 *   - Week load = sum of the poses' load levels. Top load = the highest level that week.
 *   - Load spike: a week whose top load is 2 or more levels above anything the group has met
 *     so far (a first-night beginner is assumed comfortable up to level 2).
 *   - Lighter week (deload): week load lower than the week before.
 *   - Complexity = mean complexity level, in tenths, rounded half up.
 *   - One-off pose: met in exactly one week. Spaced pose: met in 3 or more weeks.
 *   - Regression offers: for every pose, the number of cohort students whose flag it carries.
 * Anti-lever "peak pose every week": a different showcase pose closes each class.
 * Break button: a student with a head-below-heart referral flag joins in week 5.
 */
(function (root) {
  "use strict";

  var D = root.YC_DATA || (typeof require === "function" ? require("./yc-data.js") : null);
  var POSE = {};
  D.poses.forEach(function (p) { POSE[p.code] = p; });

  function tenths(total, n) { return n ? Math.floor((total * 20 + n) / (2 * n)) : 0; }

  function withPeaks(plan) {
    return plan.map(function (wk, i) {
      var pk = D.peaks[i];
      if (wk.indexOf(pk) >= 0) return wk.slice();
      if (wk.length && wk[wk.length - 1] === "rest") return wk.slice(0, -1).concat([pk, "rest"]);
      return wk.concat([pk]);
    });
  }

  function analyse(planIn, opts) {
    opts = opts || {};
    var plan = opts.peak ? withPeaks(planIn) : planIn.map(function (w) { return w.slice(); });
    var lj = D.lateJoiner, met = {}, ceiling = D.ceilingStart, weeks = [], weeksOf = {}, order = [];
    var prevTotal = null, lateList = [];
    plan.forEach(function (wk, w) {
      var seen = {}, gaps = [], nw = 0, total = 0, top = 0, cxs = 0, clash = 0;
      var cnt = {}; Object.keys(D.cohort.flags).forEach(function (f) { cnt[f] = D.cohort.flags[f]; });
      var lateOn = opts.late && w + 1 >= lj.week;
      if (lateOn) cnt[lj.flag] = (cnt[lj.flag] || 0) + 1;
      wk.forEach(function (c) {
        var p = POSE[c];
        if (p.pre.some(function (q) { return !met[q] && !seen[q]; })) gaps.push(c);
        if (!met[c]) nw++;
        seen[c] = true;
        total += p.load; if (p.load > top) top = p.load; cxs += p.cx;
        p.flags.forEach(function (f) { clash += cnt[f] || 0; });
        if (!weeksOf[c]) { weeksOf[c] = []; order.push(c); }
        weeksOf[c].push(w + 1);
        if (lateOn && p.flags.indexOf(lj.flag) >= 0) lateList.push([w + 1, c]);
      });
      var spike = top >= ceiling + D.spikeJump;
      if (top > ceiling) ceiling = top;
      var deload = prevTotal !== null && total < prevTotal;
      prevTotal = total;
      Object.keys(seen).forEach(function (c) { met[c] = true; });
      weeks.push({ week: w + 1, n: wk.length, load: total, top: top, cx: tenths(cxs, wk.length),
        gaps: gaps, spike: spike, deload: deload, clash: clash, "new": nw });
    });
    var reps = order.map(function (c) { return weeksOf[c].length; });
    var sum = function (f) { return weeks.reduce(function (a, x) { return a + f(x); }, 0); };
    return {
      gaps: sum(function (x) { return x.gaps.length; }),
      spikes: sum(function (x) { return x.spike ? 1 : 0; }),
      deloads: sum(function (x) { return x.deload ? 1 : 0; }),
      oneOffs: reps.filter(function (v) { return v === 1; }).length,
      spaced: reps.filter(function (v) { return v >= 3; }).length,
      distinct: order.length,
      clash: sum(function (x) { return x.clash; }),
      cxFirst: weeks[0].cx, cxLast: weeks[weeks.length - 1].cx,
      cxMax: Math.max.apply(null, weeks.map(function (x) { return x.cx; })),
      topMax: Math.max.apply(null, weeks.map(function (x) { return x.top; })),
      late: lateList,
      weeks: weeks,
      _plan: plan, _weeksOf: weeksOf, _order: order
    };
  }

  function canon() {
    return D.rungs.map(function (r) {
      var strip = function (a) { var o = {}; Object.keys(a).forEach(function (k) { if (k.charAt(0) !== "_") o[k] = a[k]; }); return o; };
      return { id: r.id, plain: strip(analyse(r.plan)), peak: strip(analyse(r.plan, { peak: true })),
        late: strip(analyse(r.plan, { late: true })) };
    });
  }

  /* own plan: 8 lines, pose codes or names separated by commas */
  function parsePlan(txt) {
    var byName = {};
    D.poses.forEach(function (p) { byName[p.code] = p.code; byName[p.name.toLowerCase()] = p.code; });
    var lines = (txt || "").split(/\n/).map(function (l) { return l.trim(); }).filter(function (l) { return l; });
    var plan = [], bad = [];
    lines.forEach(function (l, i) {
      var wk = [];
      l.replace(/^week\s*\d+\s*[:.-]?\s*/i, "").split(/,/).forEach(function (t) {
        var k = t.trim().toLowerCase(); if (!k) return;
        var c = byName[k];
        if (!c) bad.push("week " + (i + 1) + ": " + t.trim());
        else if (wk.indexOf(c) < 0) wk.push(c);
      });
      plan.push(wk);
    });
    return { plan: plan, bad: bad };
  }

  var api = { D: D, POSE: POSE, analyse: analyse, canon: canon, withPeaks: withPeaks, parsePlan: parsePlan, tenths: tenths };
  if (typeof module !== "undefined" && module.exports) { module.exports = api; return; }
  root.YC = api;

  /* ------------------------------------------------------------------ browser UI */
  function esc(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }
  function cx1(t) { return (t / 10).toFixed(1); }

  var state = { rung: 4, peak: false, late: false, who: "j", own: null };
  var els = {}, rootEl;

  function currentPlan() { return state.who === "o" && state.own ? state.own : D.rungs[state.rung - 1].plan; }

  function chart(a) {
    var W = 880, H = 300, X0 = 70, X1 = 840, Y0 = 220, Y1 = 60;
    var step = (X1 - X0) / 8, bw = 46;
    var maxLoad = 60, maxCx = 50;
    var y = function (v) { return Y0 - (Y0 - Y1) * v / maxLoad; };
    var yc = function (v) { return Y0 - (Y0 - Y1) * v / maxCx; };
    var s = '<svg viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Weekly load bars and complexity line for the plan. Week loads: ' +
      a.weeks.map(function (w) { return w.load; }).join(", ") + '. Prerequisite gaps: ' + a.gaps + '. Load spikes: ' + a.spikes + '.">';
    s += '<rect x="30" y="14" width="14" height="12" rx="2" fill="#E8C5CC" stroke="#A14D5E" stroke-width="1"/><text class="ab-cap" x="50" y="24">week load (sum of levels)</text>';
    s += '<path d="M232 20 h22" stroke="#6B7A2E" stroke-width="2.6"/><circle cx="243" cy="20" r="3.5" fill="#6B7A2E"/><text class="ab-cap" x="262" y="24">mean complexity, right scale</text>';
    s += '<circle cx="472" cy="20" r="6" fill="none" stroke="#991B1B" stroke-width="2"/><text class="ab-cap" x="484" y="24">load spike</text>';
    s += '<rect x="560" y="13" width="18" height="14" rx="7" fill="#FEF2F2" stroke="#991B1B" stroke-width="1"/><text class="ab-cap" x="584" y="24">prerequisite gaps</text>';
    [0, 20, 40, 60].forEach(function (v) {
      s += '<path d="M' + (X0 - 5) + ' ' + y(v).toFixed(1) + ' H' + X0 + '" stroke="#6B5A5E" stroke-width="1.2"/>';
      s += '<text class="ab-tick" x="' + (X0 - 8) + '" y="' + (y(v) + 4).toFixed(1) + '" text-anchor="end">' + v + '</text>';
    });
    [1, 3, 5].forEach(function (v) {
      s += '<text class="ab-tick" x="' + (X1 + 8) + '" y="' + (yc(v * 10) + 4).toFixed(1) + '">' + v + '</text>';
    });
    var pts = [];
    a.weeks.forEach(function (w, i) {
      var cxp = X0 + step * i + step / 2, top = y(w.load);
      s += '<rect x="' + (cxp - bw / 2).toFixed(1) + '" y="' + top.toFixed(1) + '" width="' + bw + '" height="' + (Y0 - top).toFixed(1) + '" rx="4" fill="' + (w.deload ? "#FBF0F2" : "#E8C5CC") + '" stroke="#A14D5E" stroke-width="1.4"' + (w.deload ? ' stroke-dasharray="4 3"' : '') + '/>';
      s += '<text class="ab-val" x="' + cxp.toFixed(1) + '" y="' + (top - 6).toFixed(1) + '" text-anchor="middle">' + w.load + '</text>';
      if (w.spike) s += '<circle cx="' + cxp.toFixed(1) + '" cy="' + (top - 26).toFixed(1) + '" r="9" fill="none" stroke="#991B1B" stroke-width="2.2"/>';
      if (w.gaps.length) s += '<rect x="' + (cxp - 14).toFixed(1) + '" y="' + (Y0 + 36) + '" width="28" height="18" rx="9" fill="#FEF2F2" stroke="#991B1B" stroke-width="1"/><text class="ab-lab" x="' + cxp.toFixed(1) + '" y="' + (Y0 + 49) + '" text-anchor="middle" style="fill:#991B1B">' + w.gaps.length + '</text>';
      s += '<text class="ab-tick" x="' + cxp.toFixed(1) + '" y="' + (Y0 + 18) + '" text-anchor="middle">wk ' + w.week + (w.deload ? ' · lighter' : '') + '</text>';
      pts.push([cxp, yc(w.cx)]);
    });
    s += '<path d="M' + pts.map(function (p) { return p[0].toFixed(1) + ' ' + p[1].toFixed(1); }).join(' L') + '" fill="none" stroke="#6B7A2E" stroke-width="2.6" stroke-linejoin="round"/>';
    pts.forEach(function (p) { s += '<circle cx="' + p[0].toFixed(1) + '" cy="' + p[1].toFixed(1) + '" r="4" fill="#6B7A2E"/>'; });
    s += '<path d="M' + X0 + ' ' + Y0 + ' H' + X1 + ' M' + X0 + ' ' + Y0 + ' V' + Y1 + '" stroke="#6B5A5E" stroke-width="1.2"/>';
    s += '<text class="ab-cap" x="' + X0 + '" y="' + (H - 12) + '">Constructed plan and levels. Gap badges sit under the week they happen in.</text>';
    return s + '</svg>';
  }

  function spacing(a) {
    var fams = {}, famOrder = [];
    a._order.forEach(function (c) { var f = POSE[c].family; if (!fams[f]) { fams[f] = []; famOrder.push(f); } fams[f].push(c); });
    var h = '<table class="yc-grid"><thead><tr><th scope="col">Pose</th>';
    for (var w = 1; w <= 8; w++) h += '<th scope="col">' + w + '</th>';
    h += '<th scope="col">weeks</th></tr></thead><tbody>';
    famOrder.forEach(function (f) {
      h += '<tr class="yc-fam"><th colspan="10" scope="rowgroup">' + esc(f) + '</th></tr>';
      fams[f].forEach(function (c) {
        var wk = a._weeksOf[c], n = wk.length;
        h += '<tr class="' + (n === 1 ? 'is-once' : n >= 3 ? 'is-spaced' : '') + '"><td class="yc-pose">' + esc(POSE[c].name) + '</td>';
        for (var w2 = 1; w2 <= 8; w2++) {
          var on = wk.indexOf(w2) >= 0, gap = on && a.weeks[w2 - 1].gaps.indexOf(c) >= 0;
          h += '<td>' + (gap ? '<span class="yc-dot is-gap" title="prerequisite not met">!</span>' : on ? '<span class="yc-dot" aria-label="in week ' + w2 + '"></span>' : '') + '</td>';
        }
        h += '<td class="yc-n">' + n + (n === 1 ? ' · once' : '') + '</td></tr>';
      });
    });
    return h + '</tbody></table>';
  }

  function metric(label, val, unit) {
    return '<div class="mb-metric"><span class="mb-mkind is-heuristic">modelled</span><span class="mb-mlabel">' + esc(label) + '</span><span class="mb-mvalue">' + esc(val) + '</span><span class="mb-munit">' + esc(unit) + '</span></div>';
  }

  function render() {
    var plan = currentPlan();
    var a = analyse(plan, { peak: state.peak, late: state.late });
    var name = state.who === "o" ? "Your plan" : "Rung " + state.rung;
    var cls = (a.gaps === 0 && a.spikes === 0 && a.oneOffs <= 2 && a.cxLast > a.cxFirst) ? "is-good" : (a.gaps > 4 || a.spikes > 0) ? "is-bad" : "is-ok";
    var v = name + ": " + a.gaps + " prerequisite " + (a.gaps === 1 ? "gap" : "gaps") + ", " + a.spikes + " load " + (a.spikes === 1 ? "spike" : "spikes") + ", " +
      a.oneOffs + " one-off " + (a.oneOffs === 1 ? "pose" : "poses") + ", complexity " + cx1(a.cxFirst) + " to " + cx1(a.cxLast);
    els.verdict.className = "mb-verdict " + cls; els.verdict.textContent = v;
    els.metrics.innerHTML =
      metric("Prerequisite gaps", a.gaps, "poses taught before their foundations") +
      metric("Load spikes", a.spikes, "weeks 2+ levels above anything met") +
      metric("Lighter weeks", a.deloads, "weeks lighter than the week before") +
      metric("One-off poses", a.oneOffs, "of " + a.distinct + " met in a single week") +
      metric("Spaced poses", a.spaced, "of " + a.distinct + " met in 3 or more weeks") +
      metric("Complexity, week 1 to 8", cx1(a.cxFirst) + " to " + cx1(a.cxLast), "mean level, highest " + cx1(a.cxMax)) +
      metric("Regression offers", a.clash, "student-pose clashes across 8 weeks") +
      metric("Top load met", a.topMax, "level, on a 1 to 5 scale");
    els.chart.innerHTML = chart(a);
    if (state.late) {
      var rows = a.late.map(function (x) { var p = POSE[x[1]]; return '<li><b>Week ' + x[0] + ' · ' + esc(p.name) + '</b>: offer ' + esc(p.reg) + '</li>'; });
      els.late.innerHTML = '<h4>Week 5: a new student joins <span class="mb-mkind is-heuristic">constructed</span></h4><p class="mb-hint">Flag: ' + esc(D.flagLabel[D.lateJoiner.flag]) + '. Planned poses from week 5 that need a regression ready:</p>' +
        (rows.length ? '<ol class="yc-late">' + rows.join("") + '</ol>' : '<p class="mb-hint">None. No planned pose from week 5 puts the head below the heart.</p>') +
        '<p class="mb-hint">' + rows.length + (rows.length === 1 ? ' pose needs' : ' poses need') + ' a ready option. A referral flag means you adapt and suggest they check with their clinician; it never means you assess the condition.</p>';
      els.late.hidden = false;
    } else { els.late.hidden = true; }
    els.grid.innerHTML = spacing(a);
    els.rungs.forEach(function (x) { x.parentNode.classList.toggle("is-on", +x.value === state.rung && state.who === "j"); x.checked = +x.value === state.rung; });
    els.peak.parentNode.classList.toggle("is-on", state.peak);
    els.lateBox.parentNode.classList.toggle("is-on", state.late);
  }

  function planText(plan) { return plan.map(function (wk, i) { return "week " + (i + 1) + ": " + wk.join(", "); }).join("\n"); }

  function readOwn() {
    var r = parsePlan(els.own.value), msg = [];
    if (r.plan.length !== 8) msg.push("write exactly 8 lines, one per week (found " + r.plan.length + ")");
    r.plan.forEach(function (wk, i) { if (!wk.length) msg.push("week " + (i + 1) + " is empty"); });
    if (r.bad.length) msg.push("unknown pose " + r.bad.slice(0, 4).join("; "));
    if (msg.length) { els.ownMsg.textContent = "Not run: " + msg.join("; ") + "."; return false; }
    state.own = r.plan;
    els.ownMsg.textContent = "Running your plan: 8 weeks, " + r.plan.reduce(function (a, w) { return a + w.length; }, 0) + " pose slots. It stays in this tab; nothing is stored or sent.";
    return true;
  }

  function build() {
    rootEl.innerHTML = "";
    var wrap = document.createElement("div"); wrap.className = "mb-wrap"; rootEl.appendChild(wrap);
    wrap.innerHTML = '<h4>The programme bench <span class="mb-mkind is-heuristic">constructed</span></h4><p class="mb-intro">Juniper Studio\'s 8-week beginner programme, computed in your browser. The 42-pose library, its 1 to 5 levels, the 12-student cohort and every plan are constructed for teaching; none is a measurement of real people. Not medical advice.</p>';

    var who = document.createElement("div"); who.className = "ab-top";
    who.innerHTML = '<div class="ab-pick" role="radiogroup" aria-label="Whose plan">Whose plan <label class="yc-who"><input type="radio" name="yc-who" value="j" checked> Juniper ladder</label><label class="yc-who"><input type="radio" name="yc-who" value="o"> My own plan</label></div>';
    wrap.appendChild(who);

    var own = document.createElement("div"); own.className = "yc-own"; own.hidden = true;
    own.innerHTML = '<div class="mb-edit"><label for="yc-plan">Eight lines, one per week: pose codes or names, separated by commas</label>' +
      '<textarea id="yc-plan" rows="9" spellcheck="false"></textarea></div>' +
      '<p class="yc-row"><button class="btn primary" type="button" id="yc-run">Run my plan</button> <span class="mb-hint" id="yc-ownmsg">Starts as a copy of rung 4. Your plan stays in this browser tab.</span></p>';
    wrap.appendChild(own);

    var panel = document.createElement("div"); panel.className = "mb-presets"; els.rungs = [];
    D.rungs.forEach(function (g) {
      var l = document.createElement("label"); l.className = "mb-preset";
      l.innerHTML = '<input type="radio" name="yc-rung" value="' + g.id + '"><span class="mb-pname">' + g.id + " · " + esc(g.label) + '</span><span class="mb-pnote">' + esc(g.note) + "</span>";
      panel.appendChild(l); els.rungs.push(l.querySelector("input"));
    });
    wrap.appendChild(panel);

    var tog = document.createElement("div"); tog.className = "mb-presets";
    function anti(id, nm, note) {
      var l = document.createElement("label"); l.className = "mb-preset is-anti";
      l.innerHTML = '<input type="checkbox" id="' + id + '"><span class="mb-pname">' + esc(nm) + '</span><span class="mb-pnote">' + esc(note) + "</span>";
      tog.appendChild(l); return l.querySelector("input");
    }
    els.peak = anti("yc-peak", "Peak pose every week", "The anti-lever: a different showcase pose closes each class");
    els.lateBox = anti("yc-late", "Break: a new student joins in week 5", "Advised by their doctor to avoid head-below-heart poses");
    wrap.appendChild(tog);

    els.verdict = document.createElement("div"); wrap.appendChild(els.verdict);
    els.metrics = document.createElement("div"); els.metrics.className = "mb-metrics"; wrap.appendChild(els.metrics);
    els.late = document.createElement("div"); els.late.className = "ab-card yc-latecard"; els.late.hidden = true; wrap.appendChild(els.late);
    var card = document.createElement("div"); card.className = "ab-card";
    card.innerHTML = '<h4>Load and complexity, week by week <span class="mb-mkind is-heuristic">modelled</span></h4>';
    els.chart = document.createElement("div"); els.chart.className = "mb-stage"; card.appendChild(els.chart);
    wrap.appendChild(card);
    var card2 = document.createElement("div"); card2.className = "ab-card";
    card2.innerHTML = '<h4>Which pose returns in which week <span class="mb-mkind is-heuristic">modelled</span></h4><p class="mb-hint">A dot is a week the pose is taught; "!" means it was taught before its prerequisite. Rose rows are one-offs.</p>';
    els.grid = document.createElement("div"); els.grid.className = "yc-gridwrap"; card2.appendChild(els.grid);
    wrap.appendChild(card2);

    var lib = document.createElement("details"); lib.className = "card yc-lib";
    lib.innerHTML = '<summary><span class="mode self">Reference</span>The 42-pose library: codes, levels, prerequisites, flags<span class="caret">▶</span></summary><div class="body"><div class="yc-gridwrap"><table class="yc-grid yc-libt"><thead><tr><th scope="col">Code</th><th scope="col">Pose</th><th scope="col">Load</th><th scope="col">Complexity</th><th scope="col">Needs first</th><th scope="col">Flags</th></tr></thead><tbody>' +
      D.poses.map(function (p) { return '<tr><td><code>' + p.code + '</code></td><td>' + esc(p.name) + '</td><td>' + p.load + '</td><td>' + p.cx + '</td><td>' + (p.pre.join(", ") || "-") + '</td><td>' + (p.flags.join(", ") || "-") + '</td></tr>'; }).join("") +
      '</tbody></table></div><p class="mb-hint">Constructed teaching levels. Cohort flags: wrist 3, knee 2, balance 1, back 1 of 12 students.</p></div>';
    wrap.appendChild(lib);

    els.own = own.querySelector("#yc-plan"); els.ownMsg = own.querySelector("#yc-ownmsg");
    els.own.value = planText(D.rungs[3].plan);
    els.rungs.forEach(function (x) { x.addEventListener("change", function () { state.rung = +x.value; if (state.who === "o") { state.who = "j"; who.querySelector('input[value="j"]').checked = true; own.hidden = true; } render(); }); });
    els.peak.addEventListener("change", function () { state.peak = els.peak.checked; render(); });
    els.lateBox.addEventListener("change", function () { state.late = els.lateBox.checked; render(); });
    who.querySelectorAll("input").forEach(function (x) {
      x.addEventListener("change", function () {
        state.who = x.value; own.hidden = state.who !== "o";
        if (state.who === "o" && !state.own) readOwn();
        render();
      });
    });
    own.querySelector("#yc-run").addEventListener("click", function () { if (readOwn()) render(); });
    render();
  }

  function init() { rootEl = document.getElementById("programme-bench"); if (rootEl) build(); }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init); else init();
})(this);
